template <typename T>
struct TypeTag {
    static constexpr bool is_complex = false;
};

template <>
struct TypeTag<float> {
    static constexpr bool is_complex = true;
};

template <>
struct TypeTag<double> {
    static constexpr bool is_complex = true;
};

// Usage: TypeTag<int>::is_complex is false

template <typename T>
std::enable_if_t<std::is_integral_v<T>, T>
process_value(T x) {
    return x * 2; // For integers
}

template <typename T>
std::enable_if_t<std::is_floating_point_v<T>, T>
process_value(T x) {
    return x / 2.0; // For floats
}

// SFINAE selects the correct function overload
// process_value(10) -> integral overload
// process_value(10.5) -> floating overload
